        elif i == 4 and j in [headers["Si-O"], headers["Al-O"], headers["La-O/Y-O"]]:
            record_types.append("Glass_Compound_Amount")
        elif i == 5 and j in [headers["Si-O"], headers["Al-O"]]:
            record_types.append("Glass_Compound_Amount")
        else:
            record_types.append("Other")

    # Create the cell records
    cell_records = []
    for i, j, k, value, record_type in zip(table["i"], table["j"], table["k"], table["cell_value_processed"], record_types):
