import json

def process_table(table, target_cells):
    # Define the row and column headers
    row_headers = ["Annealing temperature (degC)", "DL  under 9.8N (mm)", "DL  under 19.6N (mm)", "DL  under 29.4N (mm)", "DL  under 39.2N (mm)"]
    col_headers = ["Annealing temperature (degC)", "DL  under 9.8N (mm)", "DL  under 19.6N (mm)", "DL  under 29.4N (mm)", "DL  under 39.2N (mm)", "D   L   39.2 N   C   - D   L   9.8 N   C     (mm)"]

    # Determine the record type for each cell
    cell_record = []
    for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k']):
        if col_headers[j] == "DL  under 9.8N (mm)" or col_headers[j] == "DL  under 19.6N (mm)" or col_headers[j] == "DL  under 29.4N (mm)" or col_headers[j] == "DL  under 39.2N (mm)":
            if col_headers[j] == "DL  under 9.8N (mm)" and target_cells['cell_value_processed'][target_cells['i'].index(i)] == "-272":
                record = {"value": target_cells['cell_value_processed'][target_cells['i'].index(i)], "type": "Glass_Compound_Amount", "constituent": "DL", "unit": "wt", "material": "xx"}
            elif col_headers[j] == "DL  under 19.6N (mm)" and target_cells['cell_value_processed'][target_cells['i'].index(i)] == "-270":
                record = {"value": target_cells['cell_value_processed'][target_cells['i'].index(i)], "type": "Glass_Compound_Amount", "constituent": "DL", "unit": "wt", "material": "xx"}
            elif col_headers[j] == "DL  under 29.4N (mm)" and target_cells['cell_value_processed'][target_cells['i'].index(i)] == "-260":
                record = {"value": target_cells['cell_value_processed'][target_cells['i'].index(i)], "type": "Glass_Compound_Amount", "constituent": "DL", "unit": "wt", "material": "xx"}
            elif col_headers[j] == "DL  under 39.2N (mm)" and target_cells['cell_value_processed'][target_cells['i'].index(i)] == "-254":
                record = {"value": target_cells['cell_value_processed'][target_cells['i'].index(i)], "type": "Glass_Compound_Amount", "constituent": "DL", "unit": "wt", "material": "xx"}
            else:
                record = {"value": target_cells['cell_value_processed'][target_cells['i'].index(i)], "type": "Other"}
        else:
            record = {"value": target_cells['cell_value_processed'][target_cells['i'].index(i)], "type": "Other"}
        cell_record.append(json.dumps(record))

    # Create the output dictionary
    output = {
        "cell_index": list(zip(target_cells['i'], target_cells['j'], target_cells['k'])),
        "cell_record": cell_record
    }

    return json.dumps(output)

