def determine_record_type(value, column_headers):
    if column_headers[j-1] in ["Borosilicate", "Aluminosilicate", "Lead-silicate"]:
        return "Glass_Compound_Amount"
    else:
        return "Other"

# Function to process the record
def process_record(value, column_headers, j):
    if determine_record_type(value, column_headers) == "Glass_Compound_Amount":
        if column_headers[j-1] in ["Borosilicate", "Aluminosilicate", "Lead-silicate"]:
            material = "xx"
        else:
            material = "xx"
        if column_headers[j-1] == "Borosilicate":
