import json

def process_table(table, target_cells):
    # Determine the row and column headers
    headers = table.split('\n')[0].split('|')
    row_headers = headers[1].split(' | ')
    col_headers = headers[0].split(' | ')

    # Determine the type of each cell
    cell_type = []
    for i in range(len(target_cells['cell_value_processed'])):
        if row_headers[i] in ['Bulk', 'Shiny side', 'Dull side', 'As-milled', 'Pressed 1 min', 'Pressed 3 min', 'Pressed 6 min']:
            cell_type.append('Other')
        elif row_headers[i] in ['As-quenched ribbon', 'Powders']:
            cell_type.append('Other')
        elif col_headers[target_cells['i'][i]] in ['T', 'D 23']:
            cell_type.append('Other')
        elif col_headers[target_cells['i'][i]] == 'Glass_Compound_Amount':
            cell_type.append('Glass_Compound_Amount')
        else:
            cell_type.append('Other')

    # Create the cell records
    cell_records = []
    for i in range(len(target_cells['cell_value_processed'])):
        if cell_type[i] == 'Glass_Compound_Amount':
            if col_headers[target_cells['i'][i]] == 'Glass_Compound_Amount':
                constituent = row_headers[target_cells['j'][i]]
                unit = 'mol' if 'mol%' in col_headers[target_cells['j'][i]] else 'wt'
                material = 'xx' if 'Fe60Co10Ni10Zr7B13' not in col_headers[target_cells['j'][i]] else 'Fe60Co10Ni10Zr7B13'
                cell_records.append(json.dumps({'value': target_cells['cell_value_processed'][i], 'type': 'Glass_Compound_Amount', 'constituent': constituent, 'unit': unit, 'material': material}))
            else:
                cell_records.append(json.dumps({'value': target_cells['cell_value_processed'][i], 'type': 'Other'}))
        else:
            cell_records.append(json.dumps({'value': target_cells['cell_value_processed'][i], 'type': 'Other'}))

    # Create the output dictionary
    output = {
        'cell_index': [[target_cells['i'][i], target_cells['j'][i], target_cells['k'][i]] for i in range(len(target_cells['cell_value_processed']))],
        'cell_record': cell_records
    }

    return json.dumps(output)

table = """
|             | As-quenched ribbon | As-quenched ribbon | As-quenched ribbon | Powders   | Powders       | Powders       | Powders       |
|             | Bulk               | Shiny side         | Dull side          | As-milled | Pressed 1 min | Pressed 3 min | Pressed 6 min |
| <H hf>  (T) | 22.9               | 23.2               | 22.5               | 22.8      | 22.3          | 22.3          | 22.3          |
| D 23        | 2.8                | 3.8                | 3.7                | 2.0       | 2.2           | 2.1           | 2.1           |
"""

