import json

# Define the table data
table_data = {
    "Sample": ["PG", "GCA", "GCB", "GCC", "GCD"],
    "Heat treatment": ["0", "5h at 360degC", "5h at 400degC", "15' at 440degC", "5h at 440degC"],
    "Average size of crystals (nm)": ["-", "-", "7+-1", "11+-1", "18+-1"]
}

# Define the target cells
target_cells = {
    "cell_value_processed": ["0", "7", "11", "18"],
    "i": [2, 3, 3, 3],
    "j": [1, 3, 4, 5],
    "k": [0, 0, 0, 0]
}

# Define the column headers
column_headers = list(table_data.keys())

# Define the row headers
row_headers = table_data["Sample"]

# Function to determine the record type
def determine_record_type(value, row_header, column_header):
    if column_header == "Glass_Compound_Amount" and value in ["mol%", "mol", "wt%", "wt"]:
        return "Glass_Compound_Amount"
    else:
        return "Other"

# Function to create a Glass_Compound_Amount record
def create_glass_compound_amount_record(value, row_header, column_header):
    if value.endswith("%"):
        value = value[:-1]
        if value.endswith("mol"):
            unit = "mol"
        else:
            unit = "wt"
    else:
        unit = ""
    return json.dumps({
        "value": value,
        "type": "Glass_Compound_Amount",
        "constituent": column_header,
        "unit": unit,
        "material": row_headers[row_headers.index(row_header)]
    })

# Function to create an Other record
def create_other_record(value):
    return json.dumps({
        "value": value,
        "type": "Other"
    })

# Create the cell records
cell_records = []
for i, j, k, value in zip(target_cells["i"], target_cells["j"], target_cells["k"], target_cells["cell_value_processed"]):
    row_header = row_headers[i]
    column_header = column_headers[j]
    record_type = determine_record_type(value, row_header, column_header)
    if record_type == "Glass_Compound_Amount":
        record = create_glass_compound_amount_record(value, row_header, column_header)
    else:
        record = create_other_record(value)
    cell_records.append(record)

# Create the output dictionary
output = {
    "cell_index": [[i, j, k] for i, j, k in zip(target_cells["i"], target_cells["j"], target_cells["k"])],
    "cell_record": cell_records
}

# Print the output
print(json.dumps(output, indent=4))
