import json

def process_table(table, target_cells):
    # Determine the row and column headers
    headers = table.split('\n')[0].split('|')
    row_headers = headers[1].split(' | ')
    col_headers = headers[0].split(' | ')

    # Extract the column headers that match the target cells
    col_header = [header for header in col_headers if header in target_cells['i']]

    # Determine the record type for each cell
    records = []
    for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k']):
        value = target_cells['cell_value_processed'][target_cells['i'].index(i)]
        if col_header[j-1] == 'Li/V' and row_headers[i-1] == 'E a s e (eV)':
            records.append({
                "value": value,
                "type": "Other"
            })
        elif col_header[j-1] == 'Li/V' and row_headers[i-1] != 'E a s e (eV)':
            records.append({
                "value": value,
                "type": "Glass_Compound_Amount",
                "constituent": col_header[j-1],
                "unit": "mol",
                "material": "xx"
            })
        else:
            records.append({
                "value": value,
                "type": "Other"
            })

    # Create the output dictionary
    output = {
        "cell_index": target_cells['i'] + [j+1 for j in target_cells['j']] + target_cells['k'],
        "cell_record": [json.dumps(record) for record in records]
    }

    return json.dumps(output)

table = """
| Li/V         | 0    | 0.5  | 1    | 1.5  | 2    |
| E a s e (eV) | 0.44 | 0.52 | 0.79 | 0.81 | 0.65 |
