        "Other": ["AN-102", "AZ-102", "Total"]
    }

    # Initialize the result
    result = {
        "cell_index": [],
        "cell_record": []
    }

    # Iterate over the table
    for i, value in enumerate(table["cell_value_processed"]):
        # Get the row and column headers
        row_header = table["i"][i]
        col_header = table["j"][i]

        # Determine the record type
        if col_header in record_types["Glass_Compound_Amount"]:
            record_type = "Glass_Compound_Amount"
        else:
            record_type = "Other"

