def determine_record_type(row, col):
    if row in ["Ph 1(F2)", "Ph 2 A(F2)", "Ph 2 A(ArF)", "Ph 2 A(KrF)"]:
        if col in ["b", "d", "e", "f"]:
            if row == "Ph 1(F2)" and col in ["b", "d", "e", "f"]:
                return "Other"
            elif row == "Ph 2 A(F2)" and col in ["d", "e", "f"]:
                return "Other"
            elif row == "Ph 2 A(ArF)" and col == "e":
                return "Other"
            elif row == "Ph 2 A(KrF)" and col == "f":
                return "Other"
            else:
                return "Glass_Compound_Amount"
        else:
            return "Other"
    else:
        return "Other"

# Function to normalize units
def normalize_units(value, unit):
    if unit == "mol%":
        return {"value": value, "unit": "mol"}
    elif unit == "wt%":
        return {"value": value, "unit": "wt"}
    else:
        return {"value": value, "unit": value}

